CREATE TABLE t3a(id INTEGER PRIMARY KEY,w TEXT); CREATE TABLE t3b(id INTEGER PRIMARY KEY,w TEXT); CREATE TABLE t4a(id INTEGER PRIMARY KEY,x TEXT); CREATE TABLE t4b(id INTEGER PRIMARY KEY,x TEXT); CREATE TABLE t5a(id INTEGER PRIMARY KEY,y TEXT); CREATE TABLE t5b(id INTEGER PRIMARY KEY,y TEXT); CREATE TABLE t6a(id INTEGER PRIMARY KEY,z INT); CREATE TABLE t6b(id INTEGER PRIMARY KEY,z INT); CREATE VIEW dual(dummy) AS VALUES('x'); INSERT INTO t3a(id,w) VALUES(2,'two'),(3,'three'); INSERT INTO t3b(id,w) VALUES(6,'six'),(7,'seven'); INSERT INTO t4a(id,x) VALUES(2,'alice'),(4,'bob'); INSERT INTO t4b(id,x) VALUES(6,'cindy'),(8,'dave'); INSERT INTO t5a(id,y) VALUES(1,'red'),(2,'orange'),(3,'yellow'); INSERT INTO t5b(id,y) VALUES(4,'green'),(5,'blue'); INSERT INTO t6a(id,z) VALUES(3,333),(4,444); INSERT INTO t6b(id,z) VALUES(5,555),(0,1000),(9,999); CREATE VIEW t3 AS SELECT * FROM t3a UNION ALL SELECT * FROM t3b; CREATE VIEW t4 AS SELECT * FROM t4a UNION ALL SELECT * FROM t4b; CREATE VIEW t5 AS SELECT * FROM t5a UNION ALL SELECT * FROM t5b; CREATE VIEW t6 AS SELECT * FROM t6a UNION ALL SELECT * FROM t6b;